const jsApi = ['classes/APIConnectionError', 'classes/APIError', 'classes/APIPromise<T>', 'classes/APITimeoutError', 'classes/APIUserAbortError', 'classes/AuthenticationError', 'classes/BadRequestError', 'classes/InternalServerError', 'classes/NotFoundError', 'classes/PermissionDeniedError', 'classes/RateLimitError', 'classes/TypeSafeClient', 'classes/TypeSafeError', 'classes/UnprocessableEntityError', 'interfaces/ChoiceQuestion', 'interfaces/ChoiceResponse', 'interfaces/Logger', 'interfaces/ModelCard', 'interfaces/Models', 'interfaces/NoulQuestion', 'interfaces/NoulResponse', 'interfaces/Questions', 'interfaces/RequestOptions', 'interfaces/RetryPolicy', 'interfaces/ScoreQuestion', 'interfaces/ScoreResponse', 'interfaces/SystemOneRequest', 'interfaces/SystemOneRequestPayload', 'interfaces/SystemOneResult', 'interfaces/TypeSafeClientConfig', 'interfaces/Usage', 'interfaces/WithResponse', 'type-aliases/ChoiceCriteria', 'type-aliases/Description', 'type-aliases/EntryType', 'type-aliases/EnvVar', 'type-aliases/Fetch', 'type-aliases/JsonValue', 'type-aliases/LogLevel', 'type-aliases/Question', 'type-aliases/ResultFor<T>', 'type-aliases/ScoreCriteria', 'type-aliases/ScoreLegend<T>', 'type-aliases/ScoreOf<T>', 'variables/ENV', 'variables/LOG_LEVELS', 'variables/VERSION', 'functions/choice', 'functions/noul', 'functions/score'];
groups[5][1].push(...jsApi.map(path => [path.split('/')[1], `sdk/javascript/api/${path}`]));
const descriptions = { introduction: ['Introduction', 'Jev 是 TypeSafe 的旗艦模型，也是第一個 System One model。傳入 state 與 typed questions，即可取得程式能直接使用的結構化答案。'], 'introduction/quickstart': ['快速開始', '想直接開始嗎？這裡整理了立即使用 TypeSafe 所需的一切。'], 'concepts/system-one': ['System One', 'System One models 為軟體快速做出結構化決策；Jev 是 TypeSafe 的旗艦模型。'], 'concepts/state': ['State', '了解 state 是什麼、如何組織，以及如何提供 System One model 所需的 context。'], primitives: ['原語基礎（Questions）', '三種 TypeSafe question types（Choice、Score、Noul）、它們回傳的 typed answers，以及如何一次提出多個問題。'], 'primitives/choice': ['Choice', 'Choice 是從定義好的集合中選出一個選項的 System One question type。答案包含選項、各選項 probability 與 confidence。'], 'primitives/score': ['Score', 'Score 是依照有順序且具描述性的 levels 評估內容。答案包含 score、各 level 的 probability 與 confidence。'], 'primitives/noul': ['Noul', 'Noul question 會評估 yes/no 問題，並回傳答案為 yes 的 probability。'], confidence: ['Confidence', '了解 TypeSafe 如何回報 certainty、它與 probability 的差異，以及如何用它控制系統行為。'], patterns: ['Patterns', '使用 TypeSafe 建構系統的架構 patterns。'], 'patterns/fan-out': ['Speculative fan-out', '在一次 call 中送出許多 questions，包含 speculative questions，再讓程式判斷哪些結果相關。'], 'patterns/confidence-routing': ['Confidence-gated routing', '把 confidence 當作第二個軸：答案告訴你是什麼，confidence 告訴你是否該採取行動。'], 'patterns/composite-scoring': ['Composite scoring', '將複雜判斷拆成 atomic scores，再使用由程式控制的 weights 組合結果。'], 'patterns/intent-routing': ['Intent routing', '分類輸入 request，並將每個 request 導向最佳 handler：deterministic logic、specialist LLM 或 human。'], sdk: ['Client SDKs', '安裝 TypeSafe client SDK，並在應用程式中使用 typed questions 與 typed answers。'], models: ['Models', '查看可供 TypeSafe API 使用的 models 與其能力。'], api: ['API reference', '完整 HTTP API reference：將 state 與 questions 傳給 TypeSafe evaluation endpoint。'], 'agent-skill': ['Agent skill', '可直接加入 Claude Code、Codex 與其他 agent environments 的 skill。'], legal: ['Legal', 'TypeSafe 的法律文件與政策。'] };
const all = groups.flatMap(group => group[1].map(([title, path]) => ({ title, path })));
const sidebar = document.querySelector('#sidebar'); const content = document.querySelector('#content'); const searchModal = document.querySelector('#searchModal'); const searchInput = document.querySelector('#searchInput');
function renderNav() { const current = decodeURI(location.hash.slice(2)); sidebar.innerHTML = groups.map(([name, items]) => `<section class="group"><h2 class="group-title">${name}</h2>${items.map(([title, path]) => `<a class="nav-link ${current === path ? 'active' : ''}" href="#/${encodeURI(path)}">${title}</a>`).join('')}</section>`).join(''); }
function generic(title, description, path) { const isApi = path.includes('/api/'); const isCookbook = path.startsWith('cookbooks/'); const section = isApi ? 'API reference' : isCookbook ? 'Cookbook' : 'TypeSafe AI'; const code = isApi ? 'const client = new TypeSafeClient({ apiKey })\nconst result = await client.ask({ state, questions })' : isCookbook ? 'const questions = buildQuestions(state)\nconst answer = await client.ask({ state, questions })' : 'const result = await client.ask({ state, questions })'; return `<div class="hero"><div class="eyebrow">${section}</div><h1>${title}</h1><p class="lead">${description || 'TypeSafe 的文件條目與實作指南，保留英文專有名詞。'}</p></div><h2>這個條目說明什麼？</h2><p>${description || '本頁說明 TypeSafe 的相關概念、API 與實作方式。'} 將它視為一個可獨立使用的 building block，並在 application code 中保留決策控制權。</p><h2>使用方式</h2><p>先準備結構化的 <em>state</em>，再提出單一且明確的 <em>question</em>。TypeSafe 會回傳 typed result、probabilities 與 confidence，程式可以據此分流、排序或交給人工審查。</p><pre><code>${code}</code></pre><h2>實作提示</h2><ul class="next-list"><li>讓每個 question 聚焦一個可驗證的判斷。</li><li>把 threshold、weights 與 fallback policy 留在你的 code。</li><li>用 confidence 決定何時自動化、何時需要 human review。</li></ul>`; }
function render() { const path = decodeURI(location.hash.slice(2)) || 'introduction'; const item = all.find(page => page.path === path); if (!item) { content.innerHTML = '<div class="hero"><div class="eyebrow">404</div><h1>找不到頁面</h1><p class="lead">此文件條目不存在。</p><p><a href="#/introduction">返回 Introduction</a>，或使用搜尋功能尋找其他條目。</p></div>'; document.title = '找不到頁面｜TypeSafe AI'; renderNav(); return; } const [title, description] = descriptions[path] || [item.title, 'TypeSafe 的文件條目與實作指南。']; const index = all.findIndex(page => page.path === path); const previous = all[index - 1]; const next = all[index + 1]; const pager = `<nav class="pager" aria-label="頁面分頁">${previous ? `<a href="#/${encodeURI(previous.path)}">← ${previous.title}</a>` : '<span></span>'}${next ? `<a href="#/${encodeURI(next.path)}">${next.title} →</a>` : '<span></span>'}</nav>`; content.innerHTML = generic(title, description, path) + `<div class="feedback" role="group" aria-label="頁面回饋">這個頁面有幫助嗎？<br><button>是</button><button>否</button></div>${pager}`; document.title = `${title}｜TypeSafe AI`; renderNav(); scrollTo(0, 0); }
document.querySelector('#searchTrigger').onclick = () => { searchModal.hidden = false; searchInput.focus(); }; document.querySelector('#closeSearch').onclick = () => { searchModal.hidden = true; }; document.addEventListener('keydown', event => { if (event.key === 'Escape') searchModal.hidden = true; if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchModal.hidden = false; searchInput.focus(); } }); document.querySelector('#menuToggle').onclick = event => { const open = sidebar.classList.toggle('open'); event.currentTarget.setAttribute('aria-expanded', open); }; searchInput.oninput = event => { const query = event.target.value.toLowerCase(); document.querySelector('#searchResults').innerHTML = all.filter(page => `${page.title}${page.path}`.toLowerCase().includes(query)).slice(0, 15).map(page => `<a class="result" href="#/${encodeURI(page.path)}">${page.title}<small>${page.path}</small></a>`).join(''); }; document.querySelector('#themeToggle').onclick = event => { document.body.classList.toggle('dark'); event.currentTarget.setAttribute('aria-pressed', document.body.classList.contains('dark')); localStorage.dark = document.body.classList.contains('dark'); }; if (localStorage.dark === 'true') document.body.classList.add('dark'); onhashchange = render; render();
Object.assign(descriptions, { 'primitives/advanced': ['進階：結構', 'Instructions、Choice options、Score levels 與 Noul criteria 都支援 JSON structure，可把複雜資料保留在 typed question 中。'], 'introduction/machine-learning-primer': ['AI 基礎', 'TypeSafe 訓練 decision models 以產生 calibrated probabilities，而不是把生成文字當成唯一輸出。'], 'concepts/how-to-build-with-system-one': ['如何使用 TypeSafe 建構', '讓 code 保持控制權，交給 System One narrow、structured decisions，再由 application logic 組合成完整 workflow。'], 'concepts/use-case-map': ['使用案例', '依產業探索 TypeSafe use cases，並把有潛力的想法轉成可實作的 software workflow。'], 'sdk/python': ['TypeSafe Python SDK', '安裝 TypeSafe Python SDK，使用 asynchronous 或 synchronous API calls 提出 typed questions。'], 'sdk/python/usage': ['Usage', '了解 TypeSafe Python SDK 的使用 patterns：建立 client、傳入 state、提出 questions 並讀取 responses。'], 'sdk/javascript': ['JavaScript SDK', '使用 JavaScript client 建立 TypeSafe request，讓 Choice、Score 與 Noul 的結果直接進入 application code。'], 'sdk/javascript/api': ['JavaScript API reference', 'JavaScript SDK 的 API reference，包含 TypeSafeClient、errors、questions、responses 與 utility functions。'], 'sdk/python/api': ['Python API reference', 'Python clients、models、question types、responses、retries 與 exceptions 的 API reference。'], 'demos': ['Demos', '透過互動示例了解 TypeSafe 如何把自然語言 request 轉成可執行的 structured decisions。'], 'demos/smart-home': ['Smart home assistant demo', '示範 smart home assistant 如何用 TypeSafe 評估 user requests，再由程式呼叫對應的 typed functions。'], 'api': ['API reference', '完整 HTTP API reference：將 state 與 typed questions 傳給 evaluation endpoint，取得可直接使用的 structured result。'], 'models': ['Models', '查看 account 可用的 models、model cards 與適合的 evaluation 工作負載。'], 'cookbooks/consistency_noul_cookbook': ['Self-consistency：noul', '將 uncertain probabilities 導向 human review，同時保留 underlying noul values 供 audit 與後續分析。'], 'cookbooks/parallel_questions': ['Parallel questions', '在單一 TypeSafe call 中平行執行多個 regulatory questions，降低成本與 latency，並維持一致的 answers。'], 'cookbooks/llm_guardrails': ['Guardrails for LLMs', '用 TypeSafe 檢查進出 LLM app 的訊息，評估 jailbreak、severity 與 prompt injection，再由 code 決定 pass、review 或 block。'] }); render();
const baseGeneric = generic; generic = (title, description, path) => { const detail = title === 'Choice' ? '<h2>Choice response</h2><p>讀取 <code>choice</code> 取得選中的 option，讀取 <code>probabilities</code> 比較每個 option，並用 <code>confidence</code> 決定是否自動採用。</p>' : title === 'Score' ? '<h2>Score response</h2><p>Score 會回傳 ordered levels 的 <code>score</code>、各 level 的 <code>probabilities</code> 與整體 <code>confidence</code>。</p>' : title === 'Noul' ? '<h2>Noul response</h2><p>Noul 的 <code>noul</code> 是 0–1 之間的 probability，代表 statement 為真的可能性；threshold 應由你的 code 控制。</p>' : path.includes('/api/') ? '<h2>API surface</h2><p>本頁的 type、class 或 function 可與 <code>TypeSafeClient</code> 組合，並以 typed input/output 保持編譯期檢查。</p>' : ''; return baseGeneric(title, description, path).replace('<h2>使用方式</h2>', `${detail}<h2>使用方式</h2>`); }; render();
document.addEventListener('click', event => { if (event.target.matches('.feedback button')) { event.target.parentElement.dataset.submitted = 'true'; event.target.parentElement.insertAdjacentText('beforeend', ' 已收到，謝謝回饋。'); } if (event.target.matches('.nav-link')) { sidebar.classList.remove('open'); document.querySelector('#menuToggle').setAttribute('aria-expanded', 'false'); } });
const genericWithDetails = generic; generic = (title, description, path) => { if (path === 'introduction/quickstart') return `<div class="hero"><div class="eyebrow">INTRODUCTION</div><h1>快速開始</h1><p class="lead">偏好直接開始嗎？這裡整理了立即使用 TypeSafe 所需的一切。</p></div><h2>試用：Playground</h2><p>開啟 Playground 並登入，將任意文字貼上作為 state，再加入一個 question。你可以先試用 Noul：</p><pre><code>{\n  "urgency": {\n    "type": "noul",\n    "instructions": "Does this message express urgency?"\n  }\n}</code></pre><p>接著混用 Noul、Choice 與 Score，在一次 call 中取得所有結果。</p><h2>呼叫它：API</h2><p>從 dashboard 取得 API key，對 evaluation endpoint 發出 POST request；完整細節請參考 API Reference。</p><pre><code>POST https://api.typesafe.ai/v1/systemone\nAuthorization: Bearer &lt;API_KEY&gt;\nContent-Type: application/json</code></pre><h2>Request body</h2><pre><code>{\n  "state": "Hi, I've been trying to connect my Stripe account for 3 days and it keeps failing.",\n  "model": "jev-latest",\n  "questions": {\n    "department": { "type": "choice", "instructions": "Which team should handle this" },\n    "frustration": { "type": "score", "instructions": "How frustrated the customer appears" },\n    "is_urgent": { "type": "noul", "instructions": "The message conveys urgency" }\n  }\n}</code></pre><h2>用 Python SDK 寫程式</h2><pre><code>pip install typesafe-sdk\n\nfrom typesafe_sdk import Choice, Noul, Score, TypeSafeClient\nclient = TypeSafeClient()\nresponse = client.system_one(state=ticket, questions={\n  "department": Choice(instructions="Which team should handle this", criteria=criteria),\n  "frustration": Score(instructions="How frustrated the customer appears", criteria=levels),\n  "is_urgent": Noul(instructions="The message conveys urgency")\n})</code></pre><p>client 預設從環境變數讀取 <code>TYPESAFE_API_KEY</code>，並呼叫 <code>jev-latest</code>。</p><h2>用 Agent skill 開始</h2><p>可透過 Claude Code plugin 或 <code>npx skills add typesafe-ai/skills --skill typesafe-ai</code> 安裝 TypeSafe skill；詳細說明請見 Agent Skill 頁面。</p>`; return genericWithDetails(title, description, path); }; render();
const genericWithQuickstart = generic; generic = (title, description, path) => { if (path === 'introduction') return `<div class="hero"><div class="eyebrow">INTRODUCTION</div><h1>Introduction</h1><p class="lead">Jev 是 TypeSafe 的旗艦模型，也是第一個 System One model。傳入 state 與 typed questions，即可取得程式能直接使用的結構化答案。</p></div><p>Large language models（LLMs）通常產生給人閱讀的文字；當程式需要模型做出可消費的 judgment 時，文字生成與結構化決策之間就產生了 mismatch。</p><p>Jev 針對 typed <em>questions</em> 評估 <em>state</em>，直接回傳 structured results。不需要 text generation，也不需要 parsing。</p><h2>TypeSafe primitives</h2><p>TypeSafe 提供三種 AI primitives，每一種都提出不同類型的 question，並回傳不同形式的 answer。</p><div class="table-wrap"><table><thead><tr><th>Question type</th><th>Goal</th><th>Returns</th></tr></thead><tbody><tr><td><a href="#/primitives/choice">Choice</a></td><td>從選項清單中選擇</td><td><code>choice</code>、<code>probabilities</code>、<code>confidence</code></td></tr><tr><td><a href="#/primitives/score">Score</a></td><td>依 rubric 為 state 評分</td><td><code>score</code>、<code>probabilities</code>、<code>confidence</code></td></tr><tr><td><a href="#/primitives/noul">Noul</a></td><td>判斷 statement 是否為真</td><td><code>noul</code>（0–1）</td></tr></tbody></table></div><p>三種 question types 可以在一次 API call 中混用；每個 question 都會針對同一份 state 平行且獨立地評估。</p><h2>Atomic questions, composed in code</h2><p>System One models 最適合每個 question 只問一件具體、定義清楚的事。若問題需要多個因素，請拆解後在 code 中用自己的公式組合。</p><h2>Next steps</h2><ul class="next-list"><li><a href="#/introduction/quickstart">Quick Start</a> — 立即開始使用。</li><li><a href="#/confidence">Confidence</a> — 以 certainty 控制架構。</li><li><a href="#/patterns">Patterns</a> — 常見架構模式。</li></ul>`; return genericWithQuickstart(title, description, path); }; render();
const genericWithConcepts = generic; generic = (title, description, path) => { if (path === 'concepts/system-one') return `<div class="hero"><div class="eyebrow">TYPESAFE CONCEPTS</div><h1>System One</h1><p class="lead">System One models 為軟體快速做出結構化決策；Jev 是 TypeSafe 的旗艦模型，也是第一個 System One model。</p></div><p>System One model 會評估一份 state，直接回傳 typed answers 與 probabilities。它理解 natural-language input，但輸出的是 typed decisions，而非 generated text。</p><p>Jev 目前只接受 text input，包括 strings、JSON objects 與 text arrays；images、audio、video 尚未支援。</p><h2>與 LLM 的差異</h2><p>System One models 針對 calibrated decisions 訓練，probabilities 會依 outcomes 校準以表達 uncertainty；這是群體層級的 calibration，不保證單一答案一定正確。</p><div class="table-wrap"><table><thead><tr><th>Primitive</th><th>Question</th><th>Example output</th></tr></thead><tbody><tr><td>Choice</td><td>Which team should handle this ticket?</td><td><code>choice: "billing"</code></td></tr><tr><td>Score</td><td>How frustrated is this customer?</td><td><code>score: 1.4</code></td></tr><tr><td>Noul</td><td>Does this message request a refund?</td><td><code>noul: 0.95</code></td></tr></tbody></table></div><h2>在更大的 workflow 中做快速判斷</h2><p>你的 application 可以把 customer message、transactions 與 refund policy 放進 state，同時提出多個獨立 questions，再用 deterministic checks 組合答案並決定 action 或 review。</p><p>答案也包含 confidence，因此 code 可以決定何時自動處理，何時升級給 human 或 reasoning model。</p>`; if (path === 'concepts/state') return `<div class="hero"><div class="eyebrow">TYPESAFE CONCEPTS</div><h1>State</h1><p class="lead">State 是你要求 System One model 評估的內容，以及它回答 questions 所需的 context。</p></div><p>每個 request 會用一份 state 評估一個或多個 questions；所有 questions 看見相同 state，並且獨立評估。你可以在一次 request 混用 Choice、Score 與 Noul。</p><h2>State 可以只是 string</h2><pre><code>state = "My card was charged twice."</code></pre><p>State 也可以是包含相關 context、examples 與 application information 的 JSON object 或 array。把它想成提供給 expert panel、讓它做 judgment 前先閱讀的資料。</p><div class="table-wrap"><table><thead><tr><th>Format</th><th>適合內容</th><th>Example</th></tr></thead><tbody><tr><td>String</td><td>message、article、passage</td><td><code>"My card was charged twice."</code></td></tr><tr><td>Object</td><td>named fields、records、application state</td><td><code>{message, order_id}</code></td></tr><tr><td>Array</td><td>messages 或 records 序列</td><td><code>["Hi", "My card was charged twice."]</code></td></tr></tbody></table></div><h2>將 content 與 questions 分開</h2><p>State 放 content 與 supporting facts；questions 定義模型要對這些資料做的 judgments。把 refund request 與 policy 放進 state，再分別詢問是否提出 refund、policy 是否支持 refund。</p>`; return genericWithConcepts(title, description, path); }; render();
const genericWithChoice = generic; generic = (title, description, path) => { if (path === 'primitives/choice') return `<div class="hero"><div class="eyebrow">PRIMITIVES (QUESTIONS)</div><h1>Choice</h1><p class="lead">Choice 是從定義好的集合中選出一個 option 的 System One question type。答案包含選中的 option、每個 option 的 probability 與 confidence。</p></div><p>當答案屬於固定選項集合時使用 Choice，例如 ticket 應由哪個 team 處理、product 屬於哪個 category、code 使用哪種 language。若答案位於 spectrum，使用 Score；若是 yes/no，使用 Noul。</p><h2>Request structure</h2><p>每個 Choice question 包含 <code>type: "choice"</code>、模型要回答的 <code>instructions</code>，以及描述 answer options 的 <code>criteria</code> map。</p><pre><code>{\n  "state": "My running shoes arrived in the wrong size.",\n  "questions": {\n    "department": {\n      "type": "choice",\n      "instructions": "Which team should handle this?",\n      "criteria": {\n        "returns": "Exchanges, refunds, wrong or damaged items",\n        "shipping": "Delivery status, delays, lost packages",\n        "billing": "Charges, invoices, payment problems"\n      }\n    }\n  }\n}</code></pre><h2>Response structure</h2><pre><code>{\n  "type": "choice",\n  "choice": "returns",\n  "confidence": 1.0,\n  "probabilities": { "shipping": 0.0, "returns": 1.0, "billing": 0.0 }\n}</code></pre><ul class="next-list"><li><code>choice</code> 是 probability 最高的 option。</li><li><code>probabilities</code> 是涵蓋所有 options、總和為 1 的完整 distribution。</li><li><code>confidence</code> 介於 0 與 1；probability 越集中，confidence 通常越高。</li></ul><h2>一次提出多個 questions</h2><p>把 code 可能需要的 Choice questions 放在同一個 request 中。Questions 會平行評估，程式可以忽略不需要的 speculative answers；也可在大型 taxonomy 中依層級串接 Choice。</p><h2>Python SDK</h2><pre><code>from typesafe_sdk import Choice, TypeSafeClient\n\nwith TypeSafeClient() as client:\n    response = client.system_one(\n        state=ticket,\n        questions={\n            "department": Choice(\n                instructions="Which team should handle this?",\n                criteria=criteria,\n            ),\n        },\n    )\nprint(response.answers["department"].choice)</code></pre>`; return genericWithChoice(title, description, path); }; render();
const genericWithPrimitives = generic; generic = (title, description, path) => { if (path === 'primitives/score') return `<div class="hero"><div class="eyebrow">PRIMITIVES (QUESTIONS)</div><h1>Score</h1><p class="lead">Score 是依照有順序、具描述性的 levels 評估內容。答案包含 score、每個 level 的 probability 與 confidence。</p></div><p>當答案是可以用 steps 描述的 spectrum 時使用 Score，例如 bug severity、customer happiness 或 Python experience。固定選項用 Choice，yes/no 用 Noul。</p><h2>Request structure</h2><p>Score question 的 <code>criteria</code> 是由低到高排列的 ordered array，至少需要兩個、最多十個 levels。</p><pre><code>{\n  "state": "The export button crashes the settings page in Safari.",\n  "questions": {\n    "bug_severity": {\n      "type": "score",\n      "instructions": "How severe is the reported issue?",\n      "criteria": [\n        "Cosmetic; no impact to functionality",\n        "Broken or degraded feature, but workaround exists",\n        "Blocking issue; no workaround exists"\n      ]\n    }\n  }\n}</code></pre><h2>Levels 與 response</h2><p>每個 level 的 number 是它在 array 中的位置，從 0 開始。score 是 level number 的 probability-weighted mean，可以落在兩個 levels 之間。</p><pre><code>{\n  "type": "score",\n  "score": 1.3,\n  "confidence": 0.54,\n  "legend": { "0": "Cosmetic", "1": "Workaround exists", "2": "Blocking" },\n  "probabilities": { "0": 0.0, "1": 0.7, "2": 0.3 }\n}</code></pre><p><code>probabilities</code> 的總和為 1；<code>legend</code> 將 level number 對回描述；<code>confidence</code> 反映 distribution 是否集中。讀取 score 時應同時查看 probabilities 與 confidence。</p><h2>拆解複雜判斷</h2><p>將 severity、frustration、report quality 拆成多個 Score questions，在一次 request 中平行評估，再由 code normalize 各 score 並用你控制的 weights 組合。每個 Score question 只應測量一個 dimension。</p><pre><code>normalized = answer.score / (len(criteria) - 1)\npriority = 0.6 * severity + 0.3 * frustration + 0.1 * report_quality</code></pre>`; if (path === 'primitives/noul') return `<div class="hero"><div class="eyebrow">PRIMITIVES (QUESTIONS)</div><h1>Noul</h1><p class="lead">Noul question 評估 yes/no 問題，並回傳答案為 yes 的 probability。</p></div><p>當答案是 yes 或 no 時使用 Noul，例如是否要求 refund、resume 是否提及 distributed systems，或 message 是否包含個人資料。固定選項用 Choice，spectrum 用 Score。</p><h2>Writing a Noul question</h2><p>每個 Noul 只評估一個 yes/no question 或 statement。建議讓高 probability 明確代表「yes」。需要更細緻邊界時，可以加入 <code>criteria</code> 的 <code>true</code> 與 <code>false</code> 描述。</p><div class="table-wrap"><table><thead><tr><th>Field</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>Yes</td><td>固定為 <code>"noul"</code></td></tr><tr><td><code>instructions</code></td><td>Yes</td><td>要評估的 yes/no question 或 statement</td></tr><tr><td><code>criteria</code></td><td>No</td><td>可選的 <code>{true, false}</code> descriptions</td></tr></tbody></table></div><pre><code>{\n  "questions": {\n    "is_human_escalation": {\n      "type": "noul",\n      "instructions": "Is the customer asking for a human agent?"\n    },\n    "is_repeat_contact": {\n      "type": "noul",\n      "instructions": "Has the customer contacted support before?",\n      "criteria": {\n        "true": "Mentions a prior attempt or ticket",\n        "false": "No sign of previous contact"\n      }\n    }\n  }\n}</code></pre><h2>Response</h2><pre><code>{\n  "answers": {\n    "is_human_escalation": { "type": "noul", "noul": 0.99 },\n    "is_repeat_contact": { "type": "noul", "noul": 0.93 }\n  }\n}</code></pre><p><code>noul</code> 介於 0 與 1，代表答案為 yes 的 probability。Noul 不會回傳獨立的 confidence；接近 1 是強 yes，接近 0 是強 no，接近 0.5 表示兩者接近。需要 hard decision 時由你的 code 設定 threshold。</p>`; return genericWithPrimitives(title, description, path); }; render();
const genericWithConfidence = generic; generic = (title, description, path) => { if (path === 'confidence') return `<div class="hero"><div class="eyebrow">TYPESAFE FOUNDATIONS</div><h1>Confidence</h1><p class="lead">Confidence 說明 TypeSafe 如何回報 certainty、它和 probability 的差異，以及如何用它控制系統行為。</p></div><p>所有 Score 與 Choice answer 都包含 <code>probabilities</code>：Choice 是各選項的 probability，Score 是各 level 的 probability。分布集中在單一結果時代表較有把握；分布分散時代表不確定。<code>confidence</code> 將分布濃縮成 0 到 1 的單一數字，方便設定 threshold；Noul answer 不帶 confidence。</p><h2>Confidence derived from probabilities</h2><p>Confidence 是從既有 probability distribution 計算出的 statistic。TypeSafe 直接在每個 Choice 與 Score answer 回傳它；同時保留完整 <code>probabilities</code>，因此你也可以依照自己的 domain 使用其他 measure。</p><p>Choice 的分布跨越 options，Score 的分布跨越 levels。較平坦的分布代表較低 confidence：Choice 可能沒有明顯贏家，Score 可能是 levels 邊界模糊、問題多維，或 state 資訊不足。</p><h2>「我不知道」是有用的訊號</h2><p>如果智慧系統無法誠實表達不確定性，就很難值得信任。Confidence 讓模型可以告訴程式「這題我不確定」，讓不同 certainty level 對應不同系統行為。</p><h2>在程式中使用 confidence 的三條路徑</h2><ul><li><strong>High confidence：</strong>自動執行；模型的判斷清楚，可不需人工介入。</li><li><strong>Medium confidence：</strong>謹慎繼續；要求使用者確認、標記人工審查，或補充資訊。</li><li><strong>Low confidence：</strong>不要執行；交給人工、要求澄清，或 fallback 到其他系統。</li></ul><p>界線取決於風險。讀取帳戶餘額可以使用較低 threshold；核准提款等高風險動作，則應要求更高 confidence。</p><h2>Thresholds scale with risk</h2><pre><code>confidence = action.confidence; if (confidence &lt; 0.5) route_to_human(user_message); else if (confidence &gt; 0.9) confirm_then_execute(account_id); else ask_user_to_confirm(account_id);</code></pre><p><code>0.5</code> 可作為捕捉明顯不確定的起點，但正確 threshold 應依 domain、錯誤代價與實際資料校準。</p>`; return genericWithConfidence(title, description, path); }; render();
const genericWithFoundations = generic; generic = (title, description, path) => { if (path === 'introduction/machine-learning-primer') return `<div class="hero"><div class="eyebrow">TYPESAFE FOUNDATIONS</div><h1>AI primer</h1><p class="lead">TypeSafe 使用 calibrated probabilities 訓練 decision models，而不是只為 generated text 最佳化。</p></div><p>多數 AI 產品以 model 與人對話為核心；TypeSafe 的出發點不同：大規模 automation 會由 AI-to-AI 與 AI-to-software interaction 主導，因此 machine interface 比 chat interface 更重要。這稱為 <strong>Machine Native Intelligence</strong>：具備 structure、reliability、observability、testability、speed、consistency 與低成本等 software-like properties 的 AI。</p><h2>Building prod, not God</h2><p>TypeSafe 不試圖打造什麼都會的 model，而是服務 production system：讓 code 取得窄化、可檢查、可執行的 decision。輸出重點從「人讀起來舒服」轉向「在 software 裡可預測地運作」。</p><h2>Three post-training approaches</h2><div class="table-wrap"><table><thead><tr><th>方法</th><th>重點</th></tr></thead><tbody><tr><td><strong>RLHF</strong></td><td>用 human feedback 讓 pretrained model 產生人偏好的 responses，適合 chatbot。</td></tr><tr><td><strong>RLVR</strong></td><td>用 verifiable rewards 訓練 reasoning model，在數學等任務強，但通常較慢、較昂貴。</td></tr><tr><td><strong>RLCD</strong></td><td>Reinforcement learning for calibrated decisions，讓 TypeSafe 回傳 decisions 與 calibrated probabilities。</td></tr></tbody></table></div><h2>RLCD and calibrated decisions</h2><p>RLCD 的 output contract 不產生 prose，而是回傳 decisions 與 probabilities；較高 probability 應對應較高的正確機率。良好 calibration 的群體預測中，0.2 應約有 20% 正確、0.8 約有 80% 正確、1.0 應接近 100%。這是群體統計，不是單一答案的保證。</p><h2>The problems with RLHF</h2><p>RLHF 讓 model 說出人偏好的內容，對 chatbot 很有效，但也可能獎勵 sycophancy 與聽起來自信的 hallucination。Preference optimization 也可能造成 mode dropping。Human preference 與 machine trustworthiness 是不同的 optimization target。</p>`; if (path === 'concepts/how-to-build-with-system-one') return `<div class="hero"><div class="eyebrow">TYPESAFE FOUNDATIONS</div><h1>How to build with TypeSafe</h1><p class="lead">讓 code 掌握 workflow，讓 System One 提供窄化、structured 的 common-sense decisions。</p></div><p>System One 是用來打造 AI-powered software 的 model，不是自行決定下一步的 agent。它提供可嵌入 software 的 AI primitives，讓 code 保持控制權，而 model 處理非結構化資料上的 common-sense judgment。</p><h2>核心原則</h2><ul><li>用 code 維持 control flow、deterministic rules 與 side effects。</li><li>把廣泛判斷拆成窄化、typed、具明確 instructions 與 criteria 的 questions。</li><li>只提供每個 question 真正需要的 context。</li><li>使用 probabilities 與 confidence 來自動處理、要求 review 或升級。</li><li>把 independent questions 一次送出，再在 code 中組合答案。</li></ul><h2>System One 為何可組合</h2><div class="table-wrap"><table><thead><tr><th>特性</th><th>意義</th></tr></thead><tbody><tr><td>Structured</td><td>輸出符合 software types 與 JSON schema，不需從 generated prose 還原值。</td></tr><tr><td>Parallel</td><td>獨立 questions 會平行評估，不互相隱藏地改變 context。</td></tr><tr><td>Comparable</td><td>輸出可排序，直接驅動 if、threshold 與比較。</td></tr><tr><td>Fast</td><td>多數 query 約 100 ms，適合即時 request path。</td></tr><tr><td>Calibrated confidence</td><td>用 calibrated probabilities 表達 uncertainty。</td></tr><tr><td>Self-consistent</td><td>重複評估時設計為回傳穩定答案。</td></tr></tbody></table></div><h2>Design a System One workflow</h2><ol><li><strong>能用 code 就用 code。</strong></li><li><strong>分解 state：</strong>只傳與當前 questions 相關的 context。</li><li><strong>在 state 使用 structure：</strong>用 nested JSON，必要時指向特定值。</li><li><strong>分解 questions：</strong>提出 explicit、narrow、atomic 的問題。</li><li><strong>在 questions 使用 structure：</strong>用 named fields 保持 criteria 可讀。</li><li><strong>一次問很多問題：</strong>independent questions 平行執行。</li><li><strong>在 code 組合輸出：</strong>用 rules、weighted sums 或 classical ML。</li><li><strong>依 uncertainty routing：</strong>對不同 confidence 採取不同 action。</li></ol><pre><code>if answer.confidence &lt; threshold: route_to_human_review(answer)</code></pre>`; if (path === 'patterns') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Patterns</h1><p class="lead">使用 TypeSafe primitives，把 discrete、atomic decisions 組合成複雜的 system behavior。</p></div><p>TypeSafe 適合放在更大的 system 裡，為 AI-powered workflow 提供 decisions。本節假設你已理解 primitives 與 confidence。</p><div class="table-wrap"><table><thead><tr><th>Pattern</th><th>用途</th><th>優點</th></tr></thead><tbody><tr><td>Speculative Fan-Out</td><td>一次送出許多 questions，包括 speculative questions，再由 code 決定哪些相關。</td><td>Cost、Speed</td></tr><tr><td>Confidence-Gated Routing</td><td>將 confidence 作為第二個 decision axis，建立更安全的 system。</td><td>Reliability、Safety</td></tr><tr><td>Composite Scoring</td><td>將多個分析 dimension 組合成單一 score。</td><td>Cost、Reliability、Speed</td></tr><tr><td>Intent Routing</td><td>分類 user intent，routing 到適合的 handler。</td><td>Cost、Speed</td></tr></tbody></table></div><p>保留每個 atomic judgment，再由 code 明確組合，讓成本、速度、可靠性與風險都能獨立調整。</p>`; return genericWithFoundations(title, description, path); }; render();
const genericWithPatternPages = generic; generic = (title, description, path) => { if (path === 'patterns/fan-out') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Speculative fan-out</h1><p class="lead">一次送出許多 questions，包括 speculative questions，再由 code 決定哪些相關。</p></div><p>因為 TypeSafe 支援在單一 API call 傳送許多 questions，建議一次送出 system 需要的問題，再在 response 回來後用 code 判斷相關性。所有 questions 平行評估，增加問題通常不會增加 response latency。</p><h2>Example: support ticket triage</h2><p>同時分類 ticket category、bug severity、reproducible steps、refund requested 與 frustration。若 ticket 不是 bug report，就忽略 bug 相關答案；若不是 billing，就忽略 refund。這樣一次 call 取得完整 decision tree，節省 round trip。</p><pre><code>if category.choice == "bug_report" and bug_severity.score &gt; 1.5: escalate_to_engineering(ticket_id); elif category.choice == "billing" and refund.noul &gt; 0.7: route_to_billing_with_flag(ticket_id)</code></pre><p>Speculative questions 不相關時只會被 code 忽略；相關時則省下一次模型呼叫。</p>`; if (path === 'patterns/confidence-routing') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Confidence-gated routing</h1><p class="lead">答案告訴你 what；confidence 告訴你是否該 act。</p></div><p>Confidence 是建立可靠且安全系統的重要第二條 decision axis。同一個 intent 的不同 action，應依錯誤代價設定不同 threshold。</p><h2>Example: voice banking commands</h2><p>查詢 balance 是低風險；核准 transfer 是高風險。先用 Choice 判斷 intent，再按 confidence routing：</p><pre><code>if action.confidence &lt; 0.6: route_to_support_agent(account_id); elif action.choice == "check_balance": show_balance(account_id); elif action.choice == "approve_transfer" and action.confidence &gt; 0.85: approve_transfer(account_id); else: ask_user_to_confirm(account_id)</code></pre><p>0.6 floor 捕捉真正不確定的答案；balance 可接受 0.6，而 transfer 需要大於 0.85，否則要求使用者確認。</p>`; if (path === 'patterns/composite-scoring') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Composite scoring</h1><p class="lead">把複雜判斷拆成 atomic scores，再用 code 控制權重組合。</p></div><p>要同時依多個 criteria 排名時，將每個 independent dimension 分別評分，再將結果 normalize 到 0–1，使用由 code 控制的 weights 組合。這保留各個 judgment 的可見性。</p><h2>Example: resume screening</h2><p>可以分別評估 Python depth、team leadership、system design 與 generalist ability，再依職位調整權重：</p><pre><code>py = response.answers["python_depth"].score / 4; lead = response.answers["team_leadership"].score / 4; arch = response.answers["system_design"].score / 4; ic_score = (0.40 * py) + (0.10 * lead) + (0.40 * arch) + (0.10 * general)</code></pre><p>同一組個別 scores 可以組成 Senior IC 或 Engineering Manager 的不同 composite score；若排名不符合預期，只需調整 weights。</p>`; if (path === 'patterns/intent-routing') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Intent routing</h1><p class="lead">分類 incoming request，routing 到 deterministic logic、specialist LLM 或 human。</p></div><p>不同 user request 不需要相同 handler：有些只要 database lookup，有些需要 domain-specific LLM，有些需要人工。TypeSafe 可作為快速、低成本 classifier，先決定要啟用哪個 handler。</p><h2>Example: customer service routing</h2><p>用 Choice 判斷 intent，用 Score 判斷 complexity：</p><pre><code>if intent.confidence &lt; 0.5: route_to_human_agent(ticket_id); elif intent.choice == "order_status": handle_order_status(ticket_id); elif intent.choice == "product_question": handle_with_llm(ticket_id, PRODUCT_SPECIALIST); elif complexity.score &gt; 1: route_to_human_agent(ticket_id); else: handle_with_llm(ticket_id, COMPLAINT_RESOLUTION)</code></pre><p>低 confidence 時不要猜；TypeSafe 先完成分類，昂貴資源只在真正需要時啟用。</p>`; return genericWithPatternPages(title, description, path); }; render();
const genericWithPatternFixes = generic; generic = (title, description, path) => { if (path === 'patterns') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Patterns</h1><p class="lead">使用 TypeSafe primitives，把 discrete、atomic decisions 組合成複雜的 system behavior。</p></div><p>TypeSafe 適合放在更大的 system 裡，為 AI-powered workflow 提供 decisions。</p><div class="table-wrap"><table><thead><tr><th>Pattern</th><th>用途</th><th>優點</th></tr></thead><tbody><tr><td><a href="#/patterns/fan-out">Speculative Fan-Out</a></td><td>一次送出許多 questions，再由 code 決定哪些相關。</td><td>Cost、Speed</td></tr><tr><td><a href="#/patterns/confidence-routing">Confidence-Gated Routing</a></td><td>用 confidence 建立安全 routing。</td><td>Reliability、Safety</td></tr><tr><td><a href="#/patterns/composite-scoring">Composite Scoring</a></td><td>組合多個分析 dimension 成單一 score。</td><td>Cost、Reliability、Speed</td></tr><tr><td><a href="#/patterns/intent-routing">Intent Routing</a></td><td>分類 intent 並 routing 到 handler。</td><td>Cost、Speed</td></tr></tbody></table></div>`; if (path === 'patterns/fan-out') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Speculative fan-out</h1><p class="lead">一次送出許多 questions，再由 code 決定哪些相關。</p></div><p>所有 questions 平行評估，增加問題通常不會增加 response latency；不相關答案直接忽略。</p><pre><code>if category.choice == "bug_report": escalate_to_engineering(ticket_id) if bug_severity.score &gt; 1.5 else add_to_bug_backlog(ticket_id)<br>elif category.choice == "billing" and refund.noul &gt; 0.7: route_to_billing_with_flag(ticket_id)</code></pre>`; if (path === 'patterns/confidence-routing') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Confidence-gated routing</h1><p class="lead">答案告訴你 what；confidence 告訴你是否該 act。</p></div><p>不同 action 依錯誤代價設定不同 threshold；低 confidence 時交給 human。</p><pre><code>if action.confidence &lt; 0.6: route_to_support_agent(account_id)<br>elif action.choice == "check_balance": show_balance(account_id)<br>elif action.choice == "approve_transfer" and action.confidence &gt; 0.85: approve_transfer(account_id)<br>else: ask_user_to_confirm(account_id)</code></pre>`; if (path === 'patterns/composite-scoring') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Composite scoring</h1><p class="lead">把複雜判斷拆成 atomic scores，再用 code 控制權重組合。</p></div><p>各 dimension 分別評分、normalize 到 0–1，再用 weights 組合，保留每個 judgment 的可見性。</p><pre><code>py = response.answers["python_depth"].score / 4<br>lead = response.answers["team_leadership"].score / 4<br>arch = response.answers["system_design"].score / 4<br>general = response.answers["generalist"].score / 4<br>ic_score = (0.40 * py) + (0.10 * lead) + (0.40 * arch) + (0.10 * general)</code></pre>`; if (path === 'patterns/intent-routing') return `<div class="hero"><div class="eyebrow">PATTERNS</div><h1>Intent routing</h1><p class="lead">分類 incoming request，routing 到 deterministic logic、specialist LLM 或 human。</p></div><p>先用 Choice 判斷 intent，再用 Score 判斷 complexity；低 confidence 時不要猜。</p><pre><code>if intent.confidence &lt; 0.5: return route_to_human_agent(ticket_id)<br>if intent.choice == "order_status": handle_order_status(ticket_id)<br>elif intent.choice == "product_question": handle_with_llm(ticket_id, PRODUCT_SPECIALIST)<br>elif complexity.score &gt; 1: route_to_human_agent(ticket_id)<br>else: handle_with_llm(ticket_id, COMPLAINT_RESOLUTION)</code></pre>`; return genericWithPatternFixes(title, description, path); }; render();
const genericWithCookbooks = generic; generic = (title, description, path) => { if (path === 'cookbooks/consistency_choice_cookbook') return `<div class="hero"><div class="eyebrow">COOKBOOKS / SELF-CONSISTENCY</div><h1>Self-consistency: choices</h1><p class="lead">重複執行同一組 Choice rubric，觀察 label agreement 與 uncertainty。</p></div><p>這個 cookbook 對同一則 borderline moderation post 重複執行 15 次、每次一次回答 8 個 Choice questions，檢查每個 label 是否穩定。label 在 runs 之間搖擺時，同一則內容可能被 routing 到不同 queue。</p><h2>Experiment design</h2><ul><li>每個 question 有固定且互斥的 label set。</li><li>同一個 condition 使用相同 model 與設定，重複 15 次。</li><li>比較 raw plurality agreement 與加入 threshold 後的 automatic decision。</li></ul><h2>用 probability 產生 uncertain decision</h2><p>不要強迫系統採用 winner：若 top probability 低於 <code>0.60</code>，回傳 <code>uncertain</code> 並送 human review；剛好 0.60 才選 top label。這是 application policy，不是 accuracy guarantee。</p><pre><code>def choice_decision(probabilities, threshold=0.60):<br>    label, probability = max(probabilities.items(), key=lambda item: item[1])<br>    return label if probability &gt;= threshold else "uncertain"</code></pre><p>Self-consistency 衡量 repeatability，不等於 correctness；threshold 應以 labeled data 與錯誤成本校準。</p>`; if (path === 'cookbooks/parallel_questions') return `<div class="hero"><div class="eyebrow">COOKBOOKS / BATCHING</div><h1>Parallel questions</h1><p class="lead">在同一個 request 中平行詢問多個獨立 signals。</p></div><p>對同一份 state 的 questions 彼此獨立時，一次傳送它們比 sequential calls 更快，也能讓 code 在同一個 response 中組合結果。</p><h2>適合平行的問題</h2><ul><li>相同 state 上互不依賴的 Choice、Score、Noul。</li><li>只有在 code 取得結果後才需要組合的 signals。</li><li>可能用不到、但不會改變其他 question context 的 speculative questions。</li></ul><pre><code>response = client.system_one(state=ticket, questions={<br>    "topic": Choice(instructions="Which team owns this?", criteria=teams),<br>    "urgency": Score(instructions="How urgent is it?", criteria=levels),<br>    "needs_human": Noul(instructions="Does this need a human?")<br>})</code></pre><p>讓 model 做 atomic judgments，讓 code 做 routing、weighted sum 與 side effects；不要把一個 question 的結果偷偷塞進另一個 question。</p>`; if (path === 'cookbooks/date_extraction_cookbook') return `<div class="hero"><div class="eyebrow">COOKBOOKS / EXTRACTION</div><h1>Date extraction</h1><p class="lead">從自然語言文件抽取特定日期，並用 confidence 決定自動接受或人工 review。</p></div><p>文件裡可能同時出現 absolute date、relative date、不同年份或不完整日期。不要只問「文件中的日期是什麼」；要將 extraction question 綁定到清楚的 semantic role，例如 agreement 生效日、return deadline 或 kickoff call。</p><h2>結構化 extraction</h2><p>回傳 normalized date、mode、原文 evidence 與 confidence。若只抽到 month/day，讓 code 依文件日期補 year；若缺少必要 component，就標記需要 review，而不是猜。</p><pre><code>answer = response.answers["effective_date"]<br>if answer.confidence &lt; 0.60 or not answer.date:<br>    send_to_human_review(document)<br>else:<br>    save_date(answer.date)</code></pre><p>Confidence 應反映組成日期各部分的最低信心；範例中低於 0.60 或無法組成完整日期的結果會交給人。</p>`; if (path === 'cookbooks/classification_using_confidence') return `<div class="hero"><div class="eyebrow">COOKBOOKS / CLASSIFICATION</div><h1>Classification using confidence</h1><p class="lead">用一個 Choice 將 SEC annual reports 分到 75 個 industry groups，再用 confidence 決定回報細節層級。</p></div><p>每份 filing 先以一個 Choice 判斷 industry group。容易的文件 confidence 高，可以回報窄的 group；不確定時回報該 group 所屬的 broader division，避免低信心的精細 label 被當成可靠答案。</p><h2>兩層 taxonomy routing</h2><div class="table-wrap"><table><thead><tr><th>Confidence</th><th>回報</th></tr></thead><tbody><tr><td><code>&gt;= 0.90</code></td><td>Industry group，例如 28</td></tr><tr><td><code>&lt; 0.90</code></td><td>較寬的 division，例如 manufacturing</td></tr></tbody></table></div><pre><code>answer = response.answers["group"]<br>if answer.confidence &gt;= 0.90:<br>    return {"level": "group", "label": answer.choice}<br>return {"level": "division", "label": division(answer.choice)}</code></pre><p>單一 response 同時提供 winning group、probabilities 與 confidence；不必再呼叫第二個 model。Threshold 應使用自己的 labeled examples 與錯誤代價調整。</p>`; return genericWithCookbooks(title, description, path); }; render();
const genericWithMoreCookbooks = generic; generic = (title, description, path) => { if (path === 'cookbooks/consistency_noul_cookbook') return `<div class="hero"><div class="eyebrow">COOKBOOKS / SELF-CONSISTENCY</div><h1>Self-consistency: nouls</h1><p class="lead">保留底層 noul probabilities，同時把不確定結果導向 human review。</p></div><p>對同一筆 auto-insurance claim 重複執行 14 個 Noul questions 共 15 次，觀察每個 P(true) 是否穩定。小幅變化若跨過 0.5 threshold，可能直接改變 pay、deny 或 review 的 action。</p><h2>把 probability 轉成 review</h2><p>保留原始 noul 值，另加 application policy：低於 0.30 為 no，高於 0.70 為 yes，介於兩者（含邊界）為 uncertain 並交由人工。</p><pre><code>def noul_decision(probability):<br>    if probability &lt; 0.30: return "no"<br>    if probability &gt; 0.70: return "yes"<br>    return "uncertain"</code></pre><p>這是 routing policy，不是 correctness guarantee；production boundaries 應依 labeled examples 與錯誤代價設定。</p>`; if (path === 'cookbooks/function_calling') return `<div class="hero"><div class="eyebrow">COOKBOOKS / HOW-TO</div><h1>Function calling</h1><p class="lead">把自然語言 trading request 映射成 typed function 與 closed-set arguments。</p></div><p>將 user sentence 轉成 function name 與 arguments，每個 argument 都從固定清單選出，並保留 confidence。這比讓 model 直接生成任意 code 更容易檢查與 routing。</p><h2>範例</h2><div class="table-wrap"><table><thead><tr><th>Request</th><th>Typed call</th><th>Confidence</th></tr></thead><tbody><tr><td>plot rolling correlation between NVDA and SPY</td><td><code>rolling_correlation("NVDA", "SPY", "1mo")</code></td><td>0.91</td></tr><tr><td>compare NVDA AMD and MSFT</td><td><code>compare_returns(["NVDA","AMD","MSFT"], "3mo")</code></td><td>0.94</td></tr><tr><td>show Apple daily with volume</td><td><code>plot_price("AAPL", "1d", True)</code></td><td>0.75</td></tr></tbody></table></div><pre><code>response = client.system_one(state=request, questions={<br>    "function": Choice(instructions="Which function?", criteria=functions),<br>    "symbol": Choice(instructions="Which ticker?", criteria=tickers),<br>    "window": Choice(instructions="Which time window?", criteria=windows)<br>})</code></pre><p>讓 code 檢查 function confidence、argument validity 與 required fields，通過後才呼叫 ordinary typed function。</p>`; if (path === 'cookbooks/llm_guardrails') return `<div class="hero"><div class="eyebrow">COOKBOOKS / HOW-TO</div><h1>Guardrails for LLMs</h1><p class="lead">以多個 Noul 與一個 Score 先 screening input/output，再依 policy routing。</p></div><p>對 user messages 與 model replies 分別檢查 jailbreak、harmful request、medical advice、self-harm 與 broken policy 等 signals。每個 signal 是可觀察的 Noul，severity 是 Score。</p><h2>四種 action</h2><ul><li><strong>pass：</strong>沒有超過 policy threshold。</li><li><strong>review：</strong>不確定，交給人。</li><li><strong>block：</strong>高風險內容阻擋。</li><li><strong>support：</strong>self-harm 等情況導向支援流程。</li></ul><pre><code>result = screen(text, side)<br>if result["self_harm"] &gt; 0.7: return "support"<br>if result["harmful_request"] &gt; 0.7: return "block"<br>if result["severity"] &gt;= 2.0: return "block"<br>return "review" if result["max_uncertainty"] else "pass"</code></pre><p>同一個 assessment 可以套用 strict 或 permissive policy；probabilities 不變，只有 application routing policy 改變。</p>`; if (path === 'cookbooks/semantic_find') return `<div class="hero"><div class="eyebrow">COOKBOOKS / HOW-TO</div><h1>Line-by-line search</h1><p class="lead">用 Choice 排名文件行，用 Noul 判斷文件是否真的包含答案。</p></div><p>把文件切成帶有 <code>L000</code> 等 ID 的 lines。Choice 對每個 line ID 給 relevance probability；因為 probabilities 必須總和為 1，還需要同一個 request 中的 Noul 判斷是否存在答案。</p><h2>兩個問題一次完成</h2><pre><code>questions = {<br>    "where": Choice(instructions="Which line answers this query?", criteria=line_ids),<br>    "exists": Noul(instructions="Does any line answer this query?")<br>}<br>response = client.system_one(state=document, questions=questions)</code></pre><p>使用 <code>exists</code> 把結果分成 answered、partially addressed、not in document；Choice relevance 只負責告訴你該讀哪一行。</p><p>此 recipe 適合單次最多約 255 個 options 的文件；更長文件可先選 window，再在 window 內做第二次 ranking。</p>`; return genericWithMoreCookbooks(title, description, path); }; render();
const genericWithReference = generic; generic = (title, description, path) => { if (path === 'models') return `<div class="hero"><div class="eyebrow">REFERENCE</div><h1>Models</h1><p class="lead">Jev 是 TypeSafe 的旗艦 model，也是第一個 System One model；所有 model 都由同一個 <code>POST /v1/systemone</code> endpoint 提供。</p></div><div class="table-wrap"><table><thead><tr><th>Model</th><th>ID</th><th>Price</th><th>Context</th></tr></thead><tbody><tr><td>Jev 1.13</td><td><code>jev-1.13.0</code></td><td>$42 / Btok；$0.042 / Mtok</td><td>64k tokens / request</td></tr></tbody></table></div><p>Input 僅支援 text：string、JSON object 或 text array，不支援 image、audio、video。Output tokens 免費；rate limits 目前約為 250,000 tokens/second 與 1,200 requests/minute，可能動態調整。</p><h2>Aliases</h2><ul><li><code>jev-latest</code>：最新穩定 release，也是 SDK 預設值。</li><li><code>jev-preview</code>：最新 release，可能先於 stable。</li></ul><p>Alias 會隨 release 移動；若 confidence threshold 綁定特定版本，請使用 versioned model ID。Jev 不以 customer data fine-tune；請將 domain content 放在 state，將 rules 放在 instructions 與 criteria。</p><h2>列出 models</h2><pre><code>curl https://api.typesafe.ai/v1/models -H "Authorization: Bearer $TYPESAFE_API_KEY"</code></pre>`; if (path === 'api') return `<div class="hero"><div class="eyebrow">REFERENCE</div><h1>API reference</h1><p class="lead">完整 HTTP API：將 state 對應到 typed questions，取得 structured answers。</p></div><h2>Evaluation endpoint</h2><pre><code>POST https://api.typesafe.ai/v1/systemone<br>Authorization: Bearer &lt;API_KEY&gt;<br>Content-Type: application/json</code></pre><h2>Request body</h2><p><code>state</code> 可以是 string、object 或 array；<code>model</code> 指定 model；<code>questions</code> 是由自訂 key 對應 Question 的 map。</p><pre><code>{"state":"Help! My payouts have been failing.","model":"jev-latest","questions":{"is_urgent":{"type":"noul","instructions":"Does this convey urgency?"}}}</code></pre><h2>Question types</h2><div class="table-wrap"><table><thead><tr><th>Type</th><th>用途</th><th>主要回傳</th></tr></thead><tbody><tr><td>Noul</td><td>yes/no</td><td><code>noul</code> 0–1</td></tr><tr><td>Choice</td><td>從 options 選一個</td><td><code>choice</code>、<code>probabilities</code>、<code>confidence</code></td></tr><tr><td>Score</td><td>依 ordered levels 評分</td><td><code>score</code>、<code>legend</code>、<code>probabilities</code>、<code>confidence</code></td></tr></tbody></table></div><h2>Response 與 errors</h2><pre><code>{"model":"jev-latest","answers":{"is_urgent":{"type":"noul","noul":0.92}},"usage":{"input_tokens":312,"output_tokens":48}}</code></pre><p><code>401</code> 表示 API key 無效；<code>422</code> 表示 request validation 失敗；<code>429</code> 表示 rate limit；<code>529</code> 表示暫時 overloaded。遇到 429/529 使用 exponential backoff；SDK 預設會自動 retry。</p>`; if (path === 'agent-skill') return `<div class="hero"><div class="eyebrow">REFERENCE</div><h1>Agent skill</h1><p class="lead">給 Claude Code、Codex 與其他 agent environment 使用的 TypeSafe drop-in skill。</p></div><p>Skill 提供 TypeSafe API 的完整 context：三種 question types、architectural patterns，以及 structuring evaluations 的 best practices。</p><h2>Installation</h2><pre><code>claude plugin marketplace add typesafe-ai/skills<br>claude plugin install typesafe@typesafe-ai</code></pre><p>其他 agent 可從 GitHub 讀取 <code>SKILL.md</code>，或將完整 <code>skills/typesafe-ai</code> directory 複製到 agent 的 skills directory。選一種方式，避免重複安裝。</p><h2>Good vibe coding principles</h2><ul><li>先與 agent 討論並 review plan，再實作。</li><li>將 questions 與 thresholds 集中在容易 review 的位置。</li><li>不要照單全收 agent 的 assertions，要求它驗證 assumptions。</li><li>若 routing 不符合預期，檢查 questions 與 thresholds。</li></ul><p>若 agent invents request/response fields，通常是 skill 過期；先更新 skill，再重試。</p>`; if (path === 'legal') return `<div class="hero"><div class="eyebrow">REFERENCE</div><h1>Legal</h1><p class="lead">TypeSafe 的法律文件與 data-handling policies。</p></div><p>這些文件說明 TypeSafe 如何處理 account data、data retention、是否使用 user data 訓練 model，以及支配客戶使用 TypeSafe 的 agreements。</p><h2>Legal documents</h2><ul><li><strong>Data Processing Agreement：</strong>說明如何代表 customer 處理 data，包括 retention。</li><li><strong>Master Customer Agreement：</strong>適用 TypeSafe account 的一般條款。</li><li><strong>Privacy Policy：</strong>說明收集與使用哪些 data，以及不以 user data 訓練 models 的承諾。</li></ul><p>Enterprise customers 也可使用 zero data retention（ZDR）。請聯絡 <a href="mailto:privacy@typesafe.ai">privacy@typesafe.ai</a> 了解詳情。</p>`; return genericWithReference(title, description, path); }; render();
const genericWithDemos = generic; generic = (title, description, path) => { if (path === 'demos') return `<div class="hero"><div class="eyebrow">DEMOS</div><h1>Demos</h1><p class="lead">展示 TypeSafe 可以做到什麼的 interactive examples。</p></div><h2>Available demos</h2><div class="table-wrap"><table><thead><tr><th>Demo</th><th>內容</th></tr></thead><tbody><tr><td><a href="#/demos/smart-home">Smart Home Assistant Demo</a></td><td>使用 speculative questions 評估 smart home requests，必要時 fallback 到 LLM。</td></tr></tbody></table></div><p>每個 demo 都把 TypeSafe primitives 放入可執行的 application workflow，展示 code 如何保留控制權。</p>`; if (path === 'demos/smart-home') return `<div class="hero"><div class="eyebrow">DEMOS</div><h1>Smart home assistant demo</h1><p class="lead">用 TypeSafe 評估 smart home user requests 的 demo。</p></div><h2>How it works</h2><p>這個 demo 的核心 pattern 是 speculative fan-out：每個 user request 都同時評估一長串 questions，其中許多對當前 request 最後會是不相關的。</p><h2>範例：Turn off all of the lights in the house</h2><ol><li>判斷 request category：smart home command。</li><li>判斷 target domain：whole house。</li><li>判斷 device type：lights。</li><li>判斷 action：turn off。</li></ol><p>最後一題在尚未知道 request 是否針對 lights 前就先提出，因此是 speculative question；所有 questions 平行執行，最後由 code 過濾不相關結果。</p><h2>避免 sequential API calls</h2><p>若先問 category，再等待結果後問 domain、device 與 action，雖然問題較少，卻會增加 latency 與成本。一次 batch 所有 questions 才能讓 system 快速處理多種 request。</p><h2>TypeSafe 與 LLM pairing</h2><ul><li><strong>Splitting compound request：</strong>Noul 判斷是否包含多個 distinct actions；若是，由 LLM 拆成 atomic commands，再逐一交給 TypeSafe。</li><li><strong>Conversational fallback：</strong>若 TypeSafe 判斷是 general information 或 conversation，才呼叫 LLM 生成 freeform response。</li></ul><p>TypeSafe 的初始判斷速度足夠快，對整體 LLM fallback latency 的增加通常很小。</p><h2>Run it yourself</h2><p>Demo 是 Vite/React single-page app，透過 TypeSafe API 評估 requests；完整 source code 與 README 會說明本地執行方式及各段 workflow。</p>`; return genericWithDemos(title, description, path); }; render();
const genericWithSdk = generic; generic = (title, description, path) => { if (path === 'sdk/python') return `<div class="hero"><div class="eyebrow">CLIENT SDKS / PYTHON</div><h1>TypeSafe Python SDK</h1><p class="lead">使用 asynchronous 或 synchronous Python client 呼叫 TypeSafe API。</p></div><h2>安裝</h2><pre><code>uv add typesafe-sdk<br># 或 pip install typesafe-sdk</code></pre><p>在 environment 設定 <code>TYPESAFE_API_KEY</code>，再呼叫 System One：</p><pre><code>from typesafe_sdk import AsyncTypeSafeClient, Choice, Noul, Score<br><br>async with AsyncTypeSafeClient() as client:<br>    response = await client.system_one(<br>        state={"document": "I was charged twice."},<br>        questions={<br>            "billing": Noul(instructions="Is this about billing?"),<br>            "tone": Choice(instructions="What is the tone?", criteria={"calm": None, "angry": None}),<br>            "urgency": Score(instructions="How urgent?", criteria=["can wait", "today"]),<br>        },<br>    )</code></pre><p>答案會依 question type 分別出現在 <code>response.nouls</code>、<code>response.choices</code> 與 <code>response.scores</code>，可直接讀取 typed values。</p>`; if (path === 'sdk/javascript') return `<div class="hero"><div class="eyebrow">CLIENT SDKS / JAVASCRIPT</div><h1>JavaScript SDK</h1><p class="lead">供 Node.js 與 TypeScript 使用的 TypeSafe AI SDK。</p></div><h2>Quickstart</h2><p>需要 Node.js 20 或更新版本：</p><pre><code>npm install @typesafe-ai/sdk</code></pre><p>設定 <code>TYPESAFE_API_KEY</code> 後建立 client，並使用 typed question helper：</p><pre><code>import { choice, TypeSafeClient } from "@typesafe-ai/sdk";<br><br>const client = new TypeSafeClient();<br>const response = await client.systemOne({<br>  state: { document: "I was charged twice. Please fix this ASAP." },<br>  questions: {<br>    category: choice("What is this ticket about?", {<br>      billing: null, technical: null, other: null,<br>    }),<br>  },<br>});<br><br>console.log(response.answers.category.choice);</code></pre><p>Answer types 會從 questions 推導。Package 提供 ESM、CommonJS 與 TypeScript declarations。</p>`; return genericWithSdk(title, description, path); }; render();
const genericWithApiReference = generic; generic = (title, description, path) => { if (path.startsWith('sdk/javascript/api/') || path.startsWith('sdk/python/api/')) { const parts = path.split('/'); const symbol = parts.at(-1); const kind = parts.at(-2); const language = path.startsWith('sdk/javascript') ? 'JavaScript / TypeScript' : 'Python'; const label = symbol.replace(/%3C/g, '<').replace(/%3E/g, '>'); const detail = kind === 'classes' ? 'client、error 或 SDK model class' : kind === 'interfaces' ? 'typed request、response 或 configuration interface' : kind === 'type-aliases' ? '供 TypeScript type system 使用的 type alias' : kind === 'variables' ? 'SDK exported constant 或 environment setting' : kind === 'functions' ? '建立 typed question 的 helper function' : kind === 'clients' ? '同步或非同步 API client surface' : kind === 'types' ? 'Python SDK 的 question / response type' : kind === 'exceptions' ? 'API error handling exception' : kind === 'retries' ? 'retry policy 與 backoff 設定' : 'SDK API reference entry'; return `<div class="hero"><div class="eyebrow">${language} SDK / API</div><h1>${label}</h1><p class="lead">${label} 是 TypeSafe ${language} SDK 的 ${detail}。</p></div><p>此 reference entry 描述公開 API 的名稱、用途與型別契約。實際 request 仍會送到 <code>POST /v1/systemone</code>；SDK 只負責提供 typed client、question builder、response model 與錯誤處理。</p><h2>使用方式</h2><pre><code>${language.startsWith('JavaScript') ? `import { TypeSafeClient } from "@typesafe-ai/sdk";\n\nconst client = new TypeSafeClient();\nconst response = await client.systemOne({ state, questions });` : `from typesafe_sdk import TypeSafeClient\n\nwith TypeSafeClient() as client:\n    response = client.system_one(state=state, questions=questions)`}</code></pre><h2>Review checklist</h2><ul><li>確認輸入符合此 symbol 的 required fields 與型別。</li><li>讓 <code>Choice</code>、<code>Score</code>、<code>Noul</code> questions 保持 atomic。</li><li>對 <code>confidence</code>、<code>probabilities</code> 與 retry / error 結果設定明確的 application policy。</li></ul><p>完整 endpoint shape 請參閱 <a href="#/api">API reference</a>；question semantics 請參閱 <a href="#/primitives">Primitives</a>。</p>`; } if (path === 'sdk/python/usage') return `<div class="hero"><div class="eyebrow">PYTHON SDK</div><h1>Usage</h1><p class="lead">在 Python application 中建立 client、提出 typed questions，並處理 structured answers。</p></div><pre><code>from typesafe_sdk import Choice, Noul, Score, TypeSafeClient<br><br>with TypeSafeClient() as client:<br>    response = client.system_one(state=state, questions={<br>        "topic": Choice(instructions="What is this about?", criteria=topics),<br>        "urgent": Noul(instructions="Is this urgent?"),<br>        "severity": Score(instructions="How severe?", criteria=levels),<br>    })</code></pre><p>需要 asyncio 時使用 <code>AsyncTypeSafeClient</code> 與 <code>await client.system_one</code>。SDK 會處理 response typing、retry-after 與預設 backoff。</p>`; if (path === 'sdk/python/changelog' || path === 'sdk/javascript/changelog') return `<div class="hero"><div class="eyebrow">CLIENT SDK</div><h1>${title}</h1><p class="lead">SDK release notes 與相容性變更。</p></div><p>升級 SDK 前請確認 runtime version、model response shape 與 retry defaults。重大版本可能調整 exported types、client method name 或錯誤分類；production 應固定 dependency version 並執行自己的 integration tests。</p><h2>升級建議</h2><ol><li>閱讀本頁 release notes。</li><li>在 staging 執行 representative questions。</li><li>確認 confidence thresholds 與 response parsing 沒有改變。</li><li>再部署到 production。</li></ol>`; return genericWithApiReference(title, description, path); }; render();
const genericWithFinalPages = generic; generic = (title, description, path) => { if (path === 'primitives') return `<div class="hero"><div class="eyebrow">TYPESAFE CONCEPTS</div><h1>Primitives (Questions)</h1><p class="lead">Choice、Score、Noul 三種 question types，以及它們回傳的 typed answers。</p></div><p>每個 question 對同一份 state 做一個 judgment，answer 是 code 可直接消費的 typed value。所有 questions 可在同一 request 中平行評估。</p><div class="table-wrap"><table><thead><tr><th>Type</th><th>回答</th><th>回傳</th></tr></thead><tbody><tr><td>Choice</td><td>Which option?</td><td>choice、probabilities、confidence</td></tr><tr><td>Score</td><td>Which level?</td><td>score、legend、probabilities、confidence</td></tr><tr><td>Noul</td><td>Is this true?</td><td>noul（0–1）</td></tr></tbody></table></div><h2>一題一個 snap judgment</h2><p>問「Does this message convey urgency?」這類清楚、具體的問題；避免把分析與 action 決定塞進同一題。若判斷依賴多個 factors，拆成多題，再在 code 中組合。</p><h2>選擇 question type</h2><p>固定且無順序的 options 用 Choice；有 ordered spectrum 用 Score；乾淨的 yes/no 用 Noul。Noul 的 0.5 表示 yes/no 機率相等，不表示 medium skill。</p><h2>一次提出多題</h2><p>同一 state 的 questions 可以混用三種 type，平行執行；將可能需要的 speculative questions 一起送出，再讓 code 忽略不相關答案。</p><pre><code>questions = {<br>  "refund": Noul(instructions="Does the message request a refund?"),<br>  "type": Choice(instructions="What is the request?", criteria=options),<br>  "frustration": Score(instructions="How frustrated?", criteria=levels)<br>}</code></pre>`; if (path === 'primitives/advanced') return `<div class="hero"><div class="eyebrow">PRIMITIVES (QUESTIONS)</div><h1>Advanced: structure</h1><p class="lead">instructions、Choice options、Score levels 與 Noul criteria 都可以使用 JSON structure。</p></div><p>當 question 有多個 parts、需要 supporting data，或 input 本身已是 JSON 時，使用 object 或 array 比壓成一段 prose 更容易 review。</p><div class="table-wrap"><table><thead><tr><th>Field</th><th>支援格式</th></tr></thead><tbody><tr><td>instructions</td><td>string、object、array、null</td></tr><tr><td>Choice criteria value</td><td>string、object、array、null</td></tr><tr><td>Score criteria entry</td><td>string、object、array、null</td></tr><tr><td>Noul true / false</td><td>string、object、array、null</td></tr></tbody></table></div><pre><code>"instructions": {<br>  "field": {"name": "amount_due", "type": "number", "unit": "USD"},<br>  "question": "How large is the field value in source_text?"<br>}</code></pre><p>Choice option 可以用 <code>{summary, signals, not_for, examples}</code> 描述 boundary；Score level 可以用 named fields；Noul 的 true/false criteria 則用 examples 清楚畫出 yes/no 邊界。Structure 的目標是 clarity，不是把簡單問題變複雜。</p>`; if (path === 'concepts/use-case-map') return `<div class="hero"><div class="eyebrow">TYPESAFE FOUNDATIONS</div><h1>Example use cases</h1><p class="lead">從 industry 與 decision shape 探索 TypeSafe 可以放進哪些 software workflow。</p></div><h2>主要類別</h2><ul><li><strong>AI Automation Software：</strong>code 掌握 control flow，TypeSafe 處理 semantic decisions。</li><li><strong>Real-time applications：</strong>以約 150ms 的速度支援 UI 或即時 workflow。</li><li><strong>AI Map Reduce over Big Data：</strong>低成本處理大型 corpus、agent traces 與 feature extraction。</li><li><strong>Universal Verification：</strong>檢查 prompts、extractions、tool calls、citations 與 hallucinations。</li><li><strong>Harness Engineering：</strong>做 model routing、context retrieval、error detection 與 guardrails。</li></ul><h2>Decision shape 對照</h2><div class="table-wrap"><table><thead><tr><th>Shape</th><th>適合</th><th>例子</th></tr></thead><tbody><tr><td>Classification</td><td>一個 known category 勝出</td><td>intent、topic、department</td></tr><tr><td>Detection</td><td>某 property 是否存在</td><td>spam、fraud、urgency、jailbreak</td></tr><tr><td>Scoring</td><td>ordered rubric</td><td>severity、quality、relevance</td></tr><tr><td>Routing</td><td>category 選 code path</td><td>tool use、escalation、support queue</td></tr><tr><td>Search / Retrieval</td><td>自然語言 query 找 context</td><td>semantic search、RAG、knowledge lookup</td></tr><tr><td>Verification / Extraction</td><td>檢查 failure mode 或抽取 fields</td><td>citation、policy、ML features</td></tr></tbody></table></div>`; if (path === 'sdk') return `<div class="hero"><div class="eyebrow">CLIENT SDKS</div><h1>Client SDKs</h1><p class="lead">安裝 TypeSafe client SDK，在 application 中使用 typed questions 與 typed answers。</p></div><p>官方 SDK 提供 Python 與 JavaScript / TypeScript client，並以預設 retry policy 自動處理 retries。也可以直接呼叫 HTTP API。</p><div class="table-wrap"><table><thead><tr><th>SDK</th><th>開始方式</th></tr></thead><tbody><tr><td><a href="#/sdk/python">Python</a></td><td><code>uv add typesafe-sdk</code></td></tr><tr><td><a href="#/sdk/javascript">JavaScript / TypeScript</a></td><td><code>npm install @typesafe-ai/sdk</code></td></tr></tbody></table></div><p>設定 <code>TYPESAFE_API_KEY</code> 後，client 會將 state 與 questions 傳到 System One endpoint，並將 answers 映射成 language-native types。</p>`; if (path === 'sdk/python/api') return `<div class="hero"><div class="eyebrow">PYTHON SDK / API REFERENCE</div><h1>Python API reference</h1><p class="lead">Python sync / async clients、models、types、exceptions、constants 與 retries。</p></div><div class="table-wrap"><table><thead><tr><th>區域</th><th>內容</th></tr></thead><tbody><tr><td>Clients</td><td>Sync <code>Client</code> 與 Async <code>AsyncClient</code>。</td></tr><tr><td>Models</td><td>request、response、answer data models。</td></tr><tr><td>Types</td><td>Common、Questions、Responses 的 typed structures。</td></tr><tr><td>Retries / Exceptions</td><td>backoff policy 與 HTTP/API error classes。</td></tr></tbody></table></div><p>一般使用建議從 <a href="#/sdk/python">Python SDK</a> quickstart 開始；需要精細調整 timeout、retry 或 response typing 時再查本 API reference。</p>`; if (path === 'model-jaggedness/jev-1.13') return `<div class="hero"><div class="eyebrow">MODEL JAGGEDNESS</div><h1>Jev 1.13 jaggedness</h1><p class="lead">Jev 1.13 fast、calibrated，適合 common-sense judgment，但不是萬用 calculator 或 generator。</p></div><p>Jev 對 literal、structured、bounded decisions 表現最好；對額外 indirection、numeric precision 與 irrelevant context 可能變弱。以下限制應在設計與測試中明確處理。</p><div class="table-wrap"><table><thead><tr><th>Failure mode</th><th>建議</th></tr></thead><tbody><tr><td>Literal reading</td><td>寫出 exact condition 與 boundary criteria。</td></tr><tr><td>Math / counting</td><td>算術與計數放在 code。</td></tr><tr><td>Date / time</td><td>由 model extraction，日期比較與組裝由 code。</td></tr><tr><td>Indirection</td><td>減少 hops，直接指向 relevant state。</td></tr><tr><td>Large irrelevant state</td><td>先 filter，只傳 question 需要的 fields。</td></tr><tr><td>Adversarial content</td><td>明確 criteria，先測試 edge cases。</td></tr><tr><td>Generation</td><td>需要產生文字時使用 generative model。</td></tr></tbody></table></div><h2>重要原則</h2><p>不要用 Score expectation 重建精確數字；不要假設不同 Noul 或 Choice outputs 會遵守你想像的 arithmetic identity；不要把 model 當 calculator。當 answer space bounded 時，將 extraction 轉成 Choice options，讓 code 負責後續計算。</p>`; return genericWithFinalPages(title, description, path); }; render();
const genericWithRemainingCookbooks = generic; generic = (title, description, path) => { const cookbookTitles = { 'cookbooks/rerank_typesafe': 'Re-rank with TypeSafe', 'cookbooks/autoformat': 'Autoformat', 'cookbooks/skill_suggestion': 'Skill suggestion', 'cookbooks/entity_alignment': 'Knowledge graph entity alignment', 'cookbooks/classifying_rag_passages': 'Classifying RAG passages', 'cookbooks/citation_check': 'Double-checking citations', 'cookbooks/sde_cascade': 'SDE cascade', 'cookbooks/pre_parsed_value_extraction_cookbook': 'Pre-parsed value extraction', 'cookbooks/hierarchical_classification': 'Hierarchical classification', 'cookbooks/autoresearch_feature_discovery': 'Autoresearch feature discovery', 'cookbooks/consistency_noul_cookbook': 'Self-consistency: nouls' }; if (cookbookTitles[path]) { const cookbookTitle = cookbookTitles[path]; const slug = path.split('/').at(-1); const topics = { rerank_typesafe: '先用廉價的 broad signals 篩選候選，再用 TypeSafe 對候選做 semantic relevance scoring，保留可解釋的 probabilities。', autoformat: '先從未結構化輸入找出可能的 formatting decisions，再用 Choice、Score 與 Noul 驗證每個欄位，最後由 deterministic code 輸出格式。', skill_suggestion: '先用 Choice 從 skills shortlist 找出最適合的項目，再以 Noul 判斷是否真的值得建議，並使用 confidence 將不確定結果交給人工。', entity_alignment: '將不同來源的 entity candidates 對齊到同一個 knowledge graph identifier；用 Choice 選 candidate，用 Noul 驗證名稱與 context 是否一致。', classifying_rag_passages: '對 RAG passages 平行判斷 relevance、answer support 與 contradiction，將低 relevance 內容在進入 generation 前過濾。', citation_check: '逐一驗證 generated answer 的 citation 是否由 supplied evidence 支持；以 Noul 判斷 support，並把 uncertain citations 送 review。', sde_cascade: '先從文件抽取結構化候選，再用第二層 questions 驗證候選，將昂貴判斷只套用在通過第一層的 records。', pre_parsed_value_extraction_cookbook: '當 parser 已經提供候選值時，不要重新生成文字；將候選 values 放進 Choice options，讓 TypeSafe 選出最符合 state 的值。', hierarchical_classification: '先用 Choice 選 broad category，再由 code 依第一層結果建立下一層 options，必要時第二次 request 做更細分類。', autoresearch_feature_discovery: '用 TypeSafe 從 research text 找出可用的 semantic features，再將 features 作為 downstream classical ML model 的 inputs。', consistency_noul_cookbook: '重複執行 Noul rubric，保留原始 probability，將 uncertainty band 內的結果導向 human review。' }; const key = slug; return `<div class="hero"><div class="eyebrow">COOKBOOKS</div><h1>${cookbookTitle}</h1><p class="lead">${topics[key] || '以 TypeSafe primitives 建立可重複、可檢查的 workflow。'}</p></div><p>${topics[key] || '這個 cookbook 將 unstructured input 拆成 atomic questions，讓 code 保留 routing 與 side effects 的控制權。'}</p><h2>Workflow</h2><ol><li>整理只包含必要資訊的 <code>state</code>。</li><li>把每個 semantic judgment 寫成清楚的 Choice、Score 或 Noul question。</li><li>在同一 request 中平行評估 independent questions。</li><li>用 probabilities、confidence 與 deterministic code 組合結果。</li><li>為低 confidence 或不符合 policy 的結果設定 human review fallback。</li></ol><pre><code>response = client.system_one(state=state, questions=questions)<br>answer = response.answers["decision"]<br>if answer.confidence &lt; threshold:<br>    return route_to_human_review(state)<br>return apply_deterministic_action(answer)</code></pre><p>請依自己的 labeled examples、錯誤成本與 review capacity 校準 thresholds；cookbook 的數值是示範 policy，不是通用 guarantee。</p>`; } if (path === 'sdk/javascript/api') return `<div class="hero"><div class="eyebrow">JAVASCRIPT SDK / API REFERENCE</div><h1>JavaScript API reference</h1><p class="lead">JavaScript / TypeScript client、question helpers、response types 與 errors 的入口。</p></div><p>從此 index 進入 client classes、interfaces、type aliases、functions 與 constants。所有 typed API 最終呼叫 <code>systemOne</code>，並以 question key 回傳答案。</p><pre><code>import { TypeSafeClient, choice, score, noul } from "@typesafe-ai/sdk";<br>const client = new TypeSafeClient();<br>const result = await client.systemOne({ state, questions });</code></pre><p>需要完整 HTTP contract 時請參閱 <a href="#/api">API reference</a>；需要各 symbol 的細節時使用左側 API entries。</p>`; return genericWithRemainingCookbooks(title, description, path); }; render();
